};

export default Navbar;

import React, { useState, useCallback, useMemo } from 'react';
import FlagCard from './FlagCard';
import FlagGridSkeleton from './FlagGridSkeleton';
import useGreetings from '../../hooks/useGreetings';
import { useLanguage } from '../../context/LanguageContext';
import './FlagGrid.css';

const FlagGrid = () => {
  const { greetings, isLoading, error, refetch } = useGreetings();
  const { selectedCountry, setSelectedCountry } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');

  const filteredGreetings = useMemo(() => {
    const activeGreetings = greetings.filter((greeting) => greeting.isActive === true);
    if (!searchTerm) {
      return activeGreetings;
    }
    return activeGreetings.filter((greeting) =>
      greeting.countryName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [greetings, searchTerm]);

  const handleFlagSelect = useCallback(
    (countryData) => {
      setSelectedCountry(countryData);
    },
    [setSelectedCountry]
  );

  const handleSearchChange = (event) => {
    const sanitized = event.target.value.slice(0, 50);
    setSearchTerm(sanitized);
  };

  const totalActive = useMemo(
    () => greetings.filter((greeting) => greeting.isActive === true).length,
    [greetings]
  );

  return (
    <div className="flag-grid-container">
      <div className="flag-grid-search">
        <input
          type="text"
          placeholder="Buscar países..."
          value={searchTerm}
          onChange={handleSearchChange}
          maxLength={50}
          aria-label="Buscar países por nombre"
          className="flag-grid-search-input"
        />
      </div>

      {isLoading && <FlagGridSkeleton count={12} />}

      {!isLoading && error !== null && (
        <div className="flag-grid-error" role="alert">
          <p>{error}</p>
          <button onClick={refetch}>Reintentar</button>
        </div>
      )}

      {!isLoading && !error && filteredGreetings.length === 0 && searchTerm !== '' && (
        <div className="flag-grid-empty">
          <p>No se encontraron resultados para "{searchTerm}"</p>
        </div>
      )}

      {!isLoading && !error && filteredGreetings.length > 0 && (
        <div className="flag-grid" role="list" aria-label="Grilla de banderas de países">
          {filteredGreetings.map((greeting) => (
            <FlagCard
              key={greeting.countryCode}
              countryCode={greeting.countryCode}
              countryName={greeting.countryName}
              flagUrl={greeting.flagUrl}
              isSelected={
                selectedCountry !== null &&
                selectedCountry !== undefined &&
                selectedCountry.countryCode === greeting.countryCode
              }
              onSelect={handleFlagSelect}
            />
          ))}
        </div>
      )}

      <p className="flag-grid-count" aria-live="polite">
        Mostrando {filteredGreetings.length} de {totalActive} países
      </p>
    </div>
  );
};

export default FlagGrid;

import React, { useState, useCallback } from 'react';
import PropTypes from 'prop-types';

export const FlagCard = ({
  countryCode,
  countryName,
  greeting,
  formalGreeting,
  flagUrl,
  isActive,
  isSelected,
  onSelect,
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [imgError, setImgError] = useState(false);

  const handleClick = useCallback(() => {
    if (!isActive) return;
    onSelect({ countryCode, countryName, greeting, formalGreeting });
  }, [isActive, onSelect, countryCode, countryName, greeting, formalGreeting]);

  const handleKeyDown = useCallback(
    (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        handleClick();
      }
    },
    [handleClick]
  );

  const handleImageError = () => {
    setImgError(true);
  };

  const rootClassName = [
    'flag-card',
    isSelected ? 'flag-card--selected' : '',
    isHovered ? 'flag-card--hovered' : '',
    isActive ? 'flag-card--active' : 'flag-card--disabled',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div
      className={rootClassName}
      role="button"
      tabIndex={isActive ? 0 : -1}
      aria-label={`Seleccionar ${countryName} saludo: ${greeting}`}
      aria-pressed={isSelected}
      aria-disabled={!isActive}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="flag-card__image-container">
        {!imgError ? (
          <img
            src={flagUrl}
            alt={`Bandera de ${countryName}`}
            loading="lazy"
            onError={handleImageError}
            className="flag-card__image"
          />
        ) : (
          <div className="flag-card__image-placeholder">
            {countryCode}
          </div>
        )}
      </div>

      <div className="flag-card__content">
        <h3 className="flag-card__country-name">{countryName}</h3>
        <p className="flag-card__greeting">
          <span className="flag-card__label">Saludo:</span> {greeting}
        </p>
        <p className="flag-card__formal-greeting">
          <span className="flag-card__label">Formal:</span> {formalGreeting}
        </p>
      </div>

      {isSelected && (
        <div className="flag-card__selected-indicator">
          ✓ Seleccionado
        </div>
      )}
    </div>
  );
};

FlagCard.propTypes = {
  countryCode: PropTypes.string.isRequired,
  countryName: PropTypes.string.isRequired,
  greeting: PropTypes.string.isRequired,
  formalGreeting: PropTypes.string.isRequired,
  flagUrl: PropTypes.string.isRequired,
  isActive: PropTypes.bool.isRequired,
  isSelected: PropTypes.bool,
  onSelect: PropTypes.func.isRequired,
};

FlagCard.defaultProps = {
  isSelected: false,
  onSelect: () => {},
};

export default FlagCard;

import React, { useState, useEffect, useCallback } from 'react';
import DOMPurify from 'dompurify';

const GreetingDisplay = ({ countryCode, countryName, onError }) => {
  const [greetingData, setGreetingData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [retryTrigger, setRetryTrigger] = useState(0);

  const sanitizeGreetingData = (data) => {
    if (!data || typeof data !== 'object') return null;

    const sanitizedGreeting = DOMPurify.sanitize(data.greeting || '');
    const sanitizedFormalGreeting = DOMPurify.sanitize(data.formalGreeting || '');
    const sanitizedLanguage = DOMPurify.sanitize(data.language || '');
    const sanitizedCountryName = DOMPurify.sanitize(data.countryName || countryName || '');

    let validatedFlagUrl = '';
    if (data.flagUrl && typeof data.flagUrl === 'string' && data.flagUrl.startsWith('https://')) {
      validatedFlagUrl = data.flagUrl;
    }

    return {
      greeting: sanitizedGreeting,
      formalGreeting: sanitizedFormalGreeting,
      language: sanitizedLanguage,
      countryName: sanitizedCountryName,
      flagUrl: validatedFlagUrl,
    };
  };

  useEffect(() => {
    if (!countryCode || countryCode.trim() === '') {
      setGreetingData(null);
      return;
    }

    const abortController = new AbortController();
    const { signal } = abortController;

    const fetchGreeting = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const apiUrl = process.env.REACT_APP_API_URL;
        const url = `${apiUrl}/api/greetings/${countryCode}`;

        const response = await fetch(url, { signal });

        if (!response.ok) {
          if (response.status === 404) {
            throw new Error('No se encontró información de saludo para el país seleccionado.');
          } else if (response.status >= 500) {
            throw new Error('El servidor no está disponible en este momento. Por favor, intenta más tarde.');
          } else {
            throw new Error('No se pudo obtener el saludo. Por favor, intenta nuevamente.');
          }
        }

        const data = await response.json();

        if (!data || typeof data !== 'object') {
          throw new Error('La respuesta del servidor no tiene el formato esperado.');
        }

        const sanitized = sanitizeGreetingData(data);

        if (!signal.aborted) {
          setGreetingData(sanitized);
        }
      } catch (err) {
        if (err.name === 'AbortError') {
          return;
        }

        const userMessage = err.message || 'Ocurrió un error inesperado. Por favor, intenta nuevamente.';

        if (!signal.aborted) {
          setError(userMessage);
          if (typeof onError === 'function') {
            onError(err);
          }
        }
      } finally {
        if (!signal.aborted) {
          setIsLoading(false);
        }
      }
    };

    fetchGreeting();

    return () => {
      abortController.abort();
    };
  }, [countryCode, retryTrigger]);

  const handleRetry = useCallback(() => {
    setError(null);
    setRetryTrigger((prev) => prev + 1);
  }, []);

  if (isLoading) {
    return (
      <div
        className="greeting-display greeting-display--loading"
        aria-live="polite"
        role="status"
        aria-label="Cargando información del saludo"
      >
        <div className="greeting-display__spinner" aria-hidden="true"></div>
        <p className="greeting-display__loading-text">Cargando saludo...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div
        className="greeting-display greeting-display--error"
        aria-live="polite"
        role="alert"
      >
        <p className="greeting-display__error-message">{error}</p>
        <button
          className="greeting-display__retry-button"
          onClick={handleRetry}
          type="button"
        >
          Reintentar
        </button>
      </div>
    );
  }

  if (greetingData) {
    const displayCountryName = DOMPurify.sanitize(countryName || greetingData.countryName || '');

    return (
      <div
        className="greeting-display greeting-display--success"
        aria-live="polite"
      >
        <div className="greeting-display__card">
          <header className="greeting-display__header">
            {greetingData.flagUrl && (
              <img
                src={greetingData.flagUrl}
                alt={`Bandera de ${displayCountryName}`}
                className="greeting-display__flag"
              />
            )}
            <h2 className="greeting-display__country-name">{displayCountryName}</h2>
          </header>

          <div className="greeting-display__body">
            <div className="greeting-display__greeting-section">
              <p className="greeting-display__label">Saludo informal</p>
              <p
                className="greeting-display__greeting greeting-display__greeting--informal"
                lang={greetingData.language || undefined}
              >
                {greetingData.greeting}
              </p>
            </div>

            <div className="greeting-display__greeting-section">
              <p className="greeting-display__label">Saludo formal</p>
              <p
                className="greeting-display__greeting greeting-display__greeting--formal"
                lang={greetingData.language || undefined}
              >
                {greetingData.formalGreeting}
              </p>
            </div>
          </div>

          <footer className="greeting-display__footer">
            <p className="greeting-display__language">
              Idioma: {greetingData.language}
            </p>
          </footer>
        </div>
      </div>
    );
  }

  return (
    <div
      className="greeting-display greeting-display--empty"
      aria-live="polite"
    >
      <p className="greeting-display__empty-message">
        Selecciona un país para ver su saludo correspondiente.
      </p>
    </div>
  );
};

export default GreetingDisplay;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import DOMPurify from 'dompurify';

const AdminLogin = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);
  const [showPassword, setShowPassword] = useState(false);
  const [attemptCount, setAttemptCount] = useState(0);
  const [isBlocked, setIsBlocked] = useState(false);

  const navigate = useNavigate();

  const validateForm = () => {
    const trimmedUsername = username.trim();

    if (!trimmedUsername) {
      return 'El nombre de usuario no puede estar vacío.';
    }

    if (trimmedUsername.length < 3 || trimmedUsername.length > 50) {
      return 'El nombre de usuario debe tener entre 3 y 50 caracteres.';
    }

    const usernameRegex = /^[a-zA-Z0-9_-]+$/;
    if (!usernameRegex.test(trimmedUsername)) {
      return 'El nombre de usuario solo puede contener letras, números, guiones y guiones bajos.';
    }

    if (!password) {
      return 'La contraseña no puede estar vacía.';
    }

    if (password.length < 8) {
      return 'La contraseña debe tener al menos 8 caracteres.';
    }

    return null;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    setErrorMessage(null);

    const validationError = validateForm();
    if (validationError) {
      setErrorMessage(validationError);
      return;
    }

    if (isBlocked) {
      setErrorMessage('Demasiados intentos fallidos. Por favor espere 30 segundos antes de intentar nuevamente.');
      return;
    }

    if (attemptCount >= 5) {
      setErrorMessage('Demasiados intentos fallidos. Por favor espere 30 segundos antes de intentar nuevamente.');
      setIsBlocked(true);
      setTimeout(() => {
        setIsBlocked(false);
        setAttemptCount(0);
        setErrorMessage(null);
      }, 30000);
      return;
    }

    const sanitizedUsername = DOMPurify.sanitize(username.trim());

    setIsLoading(true);

    try {
      const apiUrl = process.env.REACT_APP_API_URL || '';
      const response = await fetch(`${apiUrl}/api/auth/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          username: sanitizedUsername,
          password: password,
        }),
      });

      if (response.ok) {
        const data = await response.json();
        const token = data.token;
        sessionStorage.setItem('adminToken', token);
        sessionStorage.setItem('adminUser', sanitizedUsername);
        navigate('/admin/dashboard');
      } else {
        setAttemptCount((prev) => prev + 1);
        let errorMsg = 'Credenciales incorrectas. Por favor verifique sus datos.';
        try {
          const errorData = await response.json();
          if (errorData && errorData.message) {
            errorMsg = errorData.message;
          }
        } catch {
          // usar mensaje genérico
        }
        setErrorMessage(errorMsg);
      }
    } catch (networkError) {
      setAttemptCount((prev) => prev + 1);
      setErrorMessage('No se pudo conectar con el servidor. Por favor verifique su conexión e intente nuevamente.');
    } finally {
      setIsLoading(false);
    }
  };

  const toggleShowPassword = () => {
    setShowPassword((prev) => !prev);
  };

  return (
    <div
      style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '100vh',
        backgroundColor: '#f0f2f5',
        padding: '16px',
      }}
    >
      <div
        style={{
          backgroundColor: '#ffffff',
          borderRadius: '12px',
          boxShadow: '0 4px 24px rgba(0, 0, 0, 0.12)',
          padding: '40px',
          width: '100%',
          maxWidth: '420px',
        }}
      >
        <div style={{ textAlign: 'center', marginBottom: '32px' }}>
          <h1
            style={{
              fontSize: '24px',
              fontWeight: '700',
              color: '#1a1a2e',
              margin: '0 0 8px 0',
            }}
          >
            Tsoft Greetings
          </h1>
          <p
            style={{
              fontSize: '14px',
              color: '#6b7280',
              margin: '0',
            }}
          >
            Panel de Administración
          </p>
        </div>

        <form onSubmit={handleSubmit} noValidate>
          <div style={{ marginBottom: '20px' }}>
            <label
              htmlFor="username"
              style={{
                display: 'block',
                fontSize: '14px',
                fontWeight: '600',
                color: '#374151',
                marginBottom: '6px',
              }}
            >
              Usuario
