import React, { useState, useEffect, useCallback } from 'react';
import DOMPurify from 'dompurify';

const GreetingForm = ({ initialData, onSubmit, onCancel, isLoading, error }) => {
  const defaultFormData = {
    countryCode: '',
    countryName: '',
    language: '',
    greeting: '',
    formalGreeting: '',
    flagUrl: '',
    isActive: true,
  };

  const [formData, setFormData] = useState(defaultFormData);
  const [fieldErrors, setFieldErrors] = useState({});
  const [isDirty, setIsDirty] = useState(false);

  useEffect(() => {
    if (initialData) {
      setFormData({
        countryCode: initialData.countryCode || '',
        countryName: initialData.countryName || '',
        language: initialData.language || '',
        greeting: initialData.greeting || '',
        formalGreeting: initialData.formalGreeting || '',
        flagUrl: initialData.flagUrl || '',
        isActive: initialData.isActive !== undefined ? initialData.isActive : true,
      });
    } else {
      setFormData(defaultFormData);
    }
    setFieldErrors({});
    setIsDirty(false);
  }, [initialData]);

  const validateField = (name, value) => {
    switch (name) {
      case 'countryCode': {
        if (!value || value.trim() === '') return 'El código de país es requerido.';
        if (!/^[A-Z]{2}$/.test(value)) return 'El código de país debe tener exactamente 2 letras mayúsculas (A-Z).';
        return '';
      }
      case 'countryName': {
        if (!value || value.trim() === '') return 'El nombre del país es requerido.';
        if (value.trim().length < 2) return 'El nombre del país debe tener al menos 2 caracteres.';
        if (value.trim().length > 100) return 'El nombre del país no puede superar los 100 caracteres.';
        if (/[<>"'`;&]/.test(value)) return 'El nombre del país contiene caracteres no permitidos.';
        return '';
      }
      case 'language': {
        if (!value || value.trim() === '') return 'El idioma es requerido.';
        if (value.trim().length < 2) return 'El idioma debe tener al menos 2 caracteres.';
        if (value.trim().length > 50) return 'El idioma no puede superar los 50 caracteres.';
        return '';
      }
      case 'greeting': {
        if (!value || value.trim() === '') return 'El saludo es requerido.';
        if (value.trim().length < 1) return 'El saludo debe tener al menos 1 carácter.';
        if (value.trim().length > 200) return 'El saludo no puede superar los 200 caracteres.';
        return '';
      }
      case 'formalGreeting': {
        if (!value || value.trim() === '') return 'El saludo formal es requerido.';
        if (value.trim().length < 1) return 'El saludo formal debe tener al menos 1 carácter.';
        if (value.trim().length > 200) return 'El saludo formal no puede superar los 200 caracteres.';
        return '';
      }
      case 'flagUrl': {
        if (!value || value.trim() === '') return 'La URL de la bandera es requerida.';
        if (/^javascript:/i.test(value.trim())) return 'La URL de la bandera no es válida.';
        if (/^data:/i.test(value.trim())) return 'La URL de la bandera no es válida.';
        if (!/^https:\/\/.+/.test(value.trim())) return 'La URL de la bandera debe comenzar con https://.';
        try {
          new URL(value.trim());
        } catch {
          return 'La URL de la bandera no es una URL válida.';
        }
        return '';
      }
      case 'isActive':
        return '';
      default:
        return '';
    }
  };

  const validateAllFields = () => {
    const errors = {};
    let isValid = true;

    Object.keys(formData).forEach((fieldName) => {
      const value = formData[fieldName];
      const errorMsg = validateField(fieldName, value);
      if (errorMsg) {
        errors[fieldName] = errorMsg;
        isValid = false;
      } else {
        errors[fieldName] = '';
      }
    });

    return { errors, isValid };
  };

  const handleChange = useCallback((event) => {
    const { name, value, type, checked } = event.target;
    const fieldValue = type === 'checkbox' ? checked : value;

    setFormData((prev) => ({
      ...prev,
      [name]: fieldValue,
    }));

    const errorMsg = validateField(name, fieldValue);
    setFieldErrors((prev) => ({
      ...prev,
      [name]: errorMsg,
    }));

    setIsDirty(true);
  }, []);

  const handleBlur = useCallback((event) => {
    const { name, value, type, checked } = event.target;
    const fieldValue = type === 'checkbox' ? checked : value;
    const errorMsg = validateField(name, fieldValue);
    setFieldErrors((prev) => ({
      ...prev,
      [name]: errorMsg,
    }));
  }, []);

  const handleSubmit = useCallback(
    (event) => {
      event.preventDefault();

      const { errors, isValid } = validateAllFields();

      if (!isValid) {
        setFieldErrors(errors);
        return;
      }

      const sanitizeOptions = { ALLOWED_TAGS: [], ALLOWED_ATTR: [] };

      const sanitizedData = {
        countryCode: DOMPurify.sanitize(formData.countryCode, sanitizeOptions),
        countryName: DOMPurify.sanitize(formData.countryName, sanitizeOptions),
        language: DOMPurify.sanitize(formData.language, sanitizeOptions),
        greeting: DOMPurify.sanitize(formData.greeting, sanitizeOptions),
        formalGreeting: DOMPurify.sanitize(formData.formalGreeting, sanitizeOptions),
        flagUrl: DOMPurify.sanitize(formData.flagUrl, sanitizeOptions),
        isActive: formData.isActive,
      };

      onSubmit(sanitizedData);
    },
    [formData, onSubmit]
  );

  return (
    <form onSubmit={handleSubmit} noValidate className="greeting-form">
      <h2>{initialData ? 'Editar Saludo' : 'Nuevo Saludo'}</h2>

      {error && (
        <div className="greeting-form__error-banner" role="alert">
          {error}
        </div>
      )}

      <div className="greeting-form__field-group">
        <label htmlFor="countryCode" className="greeting-form__label">
          Código de País
        </label>
        <input
          type="text"
          id="countryCode"
          name="countryCode"
          value={formData.countryCode}
          onChange={handleChange}
          onBlur={handleBlur}
          disabled={isLoading}
          maxLength={2}
          placeholder="Ej: ES"
          className={`greeting-form__input ${fieldErrors.countryCode ? 'greeting-form__input--error' : ''}`}
          aria-describedby={fieldErrors.countryCode ? 'countryCode-error' : undefined}
          aria-invalid={!!fieldErrors.countryCode}
        />
        {fieldErrors.countryCode && (
          <span id="countryCode-error" className="greeting-form__field-error" role="alert">
            {fieldErrors.countryCode}
          </span>
        )}
      </div>

      <div className="greeting-form__field-group">
        <label htmlFor="countryName" className="greeting-form__label">
          Nombre del País
        </label>
        <input
          type="text"
          id="countryName"
          name="countryName"
          value={formData.countryName}
          onChange={handleChange}
          onBlur={handleBlur}
          disabled={isLoading}
          maxLength={100}
          placeholder="Ej: España"
          className={`greeting-form__input ${fieldErrors.countryName ? 'greeting-form__input--error' : ''}`}
          aria-describedby={fieldErrors.countryName ? 'countryName-error' : undefined}
          aria-invalid={!!fieldErrors.countryName}
        />
        {fieldErrors.countryName && (
          <span id="countryName-error" className="greeting-form__field-error" role="alert">
            {fieldErrors.countryName}
          </span>
        )}
      </div>

      <div className="greeting-form__field-group">
        <label htmlFor="language" className="greeting-form__label">
          Idioma
        </label>
        <input
          type="text"
          id="language"
          name="language"
          value={formData.language}
          onChange={handleChange}
          onBlur={handleBlur}
          disabled={isLoading}
          maxLength={50}
          placeholder="Ej: Español"
          className={`greeting-form__input ${fieldErrors.language ? 'greeting-form__input--error' : ''}`}
          aria-describedby={fieldErrors.language ? 'language-error' : undefined}
          aria-invalid={!!fieldErrors.language}
        />
        {fieldErrors.language && (
          <span id="language-error" className="greeting-form__field-error" role="alert">
            {fieldErrors.language}
          </span>
        )}
      </div>

      <div className="greeting-form__field-group">
        <label htmlFor="greeting" className="greeting-form__label">
          Saludo
        </label>
        <textarea
          id="greeting"
          name="greeting"
          value={formData.greeting}
          onChange={handleChange}
          onBlur={handleBlur}
          disabled={isLoading}
          maxLength={200}
          placeholder="Ej: Hola"
          rows={3}
          className={`greeting-form__textarea ${fieldErrors.greeting ? 'greeting-form__textarea--error' : ''}`}
          aria-describedby={fieldErrors.greeting ? 'greeting-error' : undefined}
          aria-invalid={!!fieldErrors.greeting}
        />
        {fieldErrors.greeting && (
          <span id="greeting-error" className="greeting-form__field-error" role="alert">
            {fieldErrors.greeting}
          </span>
        )}
      </div>

      <div className="greeting-form__field-group">
        <label htmlFor="formalGreeting" className="greeting-form__label">
          Saludo Formal
        </label>
        <textarea
          id="formalGreeting"
          name="formalGreeting"
          value={formData.formalGreeting}
          onChange={handleChange}
          onBlur={handleBlur}
          disabled={isLoading}
          maxLength={200}
          placeholder="Ej: Buenos días"
          rows={3}
          className={`greeting-form__textarea ${fieldErrors.formalGreeting ? 'greeting-form__textarea--error' : ''}`}
          aria-describedby={fieldErrors.formalGreeting ? 'formalGreeting-error' : undefined}
          aria-invalid={!!fieldErrors.formalGreeting}
        />
        {fieldErrors.formalGreeting && (
          <span id="formalGreeting-error" className="greeting-form__field-error" role="alert">
            {fieldErrors.formalGreeting}
          </span>
        )}
      </div>

      <div className="greeting-form__field-group">
        <label htmlFor="flagUrl" className="greeting-form__label">
          URL de la Bandera
        </label>
        <input
          type="url"
          id="flagUrl"
          name="flagUrl"
          value={formData.flagUrl}
          onChange={handleChange}
          onBlur={handleBlur}
          disabled={isLoading}
          placeholder="https://ejemplo.com/bandera.svg"
          className={`greeting-form__input ${fieldErrors.flagUrl ? 'greeting-form__input--error' : ''}`}
          aria-describedby={fieldErrors.flagUrl ? 'flagUrl-error' : undefined}
          aria-invalid={!!fieldErrors.flagUrl}
        />
        {fieldErrors.flagUrl && (
          <span id="flagUrl-error" className="greeting-form__field-error" role="alert">
            {fieldErrors.flagUrl}
          </span>
        )}
      </div>

      <div className="greeting-form__field-group greeting-form__field-group--checkbox">
        <label htmlFor="isActive" className="greeting-form__label greeting-form__label--checkbox">
          <input
            type="checkbox"
            id="isActive"
            name="isActive"
            checked={formData.isActive}
            onChange={handleChange}
            onBlur={handleBlur}
            disabled={isLoading}
            className="greeting-form__checkbox"
          />
          Activo
        </label>
      </div>

      <div className="greeting-form__actions">
        <button
          type="submit"
          disabled={isLoading}
          className="greeting-form__button greeting-form__button--submit"
        >
          {isLoading ? 'Guardando...' : initialData ? 'Actualizar Saludo' : 'Crear Saludo'}
        </button>
        <button
          type="button"
          onClick={onCancel}
          disabled={isLoading}
          className="greeting-form__button greeting-form__button--cancel"
        >
          Cancelar
        </button>
      </div>
    </form>
  );
};

export default GreetingForm;

import React, { useState, useEffect } from 'react';
import DOMPurify from 'dompurify';
import { getGreetings, deleteGreeting, toggleGreetingStatus } from '../../services/greetingService';
import ConfirmModal from './ConfirmModal';

const GreetingTable = () => {
  const [greetings, setGreetings] = useState([]);
  const [filteredGreetings, setFilteredGreetings] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedGreeting, setSelectedGreeting] = useState(null);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  useEffect(() => {
    fetchGreetings();
  }, []);

  useEffect(() => {
    if (searchTerm.trim() === '') {
      setFilteredGreetings(greetings);
    } else {
      const term = searchTerm.toLowerCase();
      const filtered = greetings.filter((greeting) => {
        return (
          (greeting.countryName && greeting.countryName.toLowerCase().includes(term)) ||
          (greeting.countryCode && greeting.countryCode.toLowerCase().includes(term)) ||
          (greeting.language && greeting.language.toLowerCase().includes(term))
        );
      });
      setFilteredGreetings(filtered);
    }
    setCurrentPage(1);
  }, [searchTerm, greetings]);

  const fetchGreetings = async () => {
    try {
      const token = localStorage.getItem('token');
      const data = await getGreetings(token);
      setGreetings(data);
      setFilteredGreetings(data);
    } catch (err) {
      setError(err.message || 'Error al cargar los saludos');
    } finally {
      setLoading(false);
    }
  };

  const totalPages = Math.ceil(filteredGreetings.length / itemsPerPage);
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = filteredGreetings.slice(indexOfFirstItem, indexOfLastItem);

  const handleSearch = (e) => {
    const sanitized = DOMPurify.sanitize(e.target.value);
    const limited = sanitized.slice(0, 50);
    setSearchTerm(limited);
  };

  const handleDeleteClick = (greeting) => {
    setSelectedGreeting(greeting);
    setShowConfirmModal(true);
  };

  const handleConfirmDelete = async () => {
    try {
      const token = localStorage.getItem('token');
      await deleteGreeting(selectedGreeting._id, token);
      setGreetings((prev) => prev.filter((g) => g._id !== selectedGreeting._id));
      setShowConfirmModal(false);
      setSelectedGreeting(null);
    } catch (err) {
      setError(err.message || 'Error al eliminar el saludo');
    }
  };

  const handleToggleStatus = async (greeting) => {
    try {
      const token = localStorage.getItem('token');
      const updated = await toggleGreetingStatus(greeting._id, !greeting.isActive, token);
      setGreetings((prev) =>
        prev.map((g) =>
          g._id === greeting._id ? { ...g, isActive: updated.isActive } : g
        )
      );
    } catch (err) {
      setError(err.message || 'Error al cambiar el estado del saludo');
    }
  };

  const handlePageChange = (page) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
    }
  };

  const activeCount = greetings.filter((g) => g.isActive === true).length;

  return (
    <div className="greeting-table-container">
      <div className="greeting-table-header">
        <h2>Gestión de Saludos</h2>
        <p>Total de registros activos: <strong>{activeCount}</strong></p>
      </div>

      <div className="greeting-table-controls">
        <input
          type="text"
          placeholder="Buscar por país, código o idioma..."
          value={searchTerm}
          onChange={handleSearch}
          maxLength={50}
          aria-label="Buscar saludos por país, código o idioma"
          className="greeting-search-input"
        />
      </div>

      {error && (
        <div role="alert" className="error-message">
          <span>{error}</span>
          <button
            onClick={() => setError(null)}
            aria-label="Cerrar mensaje de error"
            className="error-close-btn"
          >
            &times;
          </button>
        </div>
      )}

      {loading ? (
        <div className="loading-spinner" aria-live="polite" aria-busy="true">
          <span className="sr-only">Cargando saludos...</span>
          <div className="spinner" aria-hidden="true"></div>
        </div>
      ) : (
        <>
          {filteredGreetings.length === 0 ? (
            <p className="no-results">No se encontraron registros.</p>
          ) : (
            <div className="table-wrapper">
              <table className="greeting-table">
                <thead>
                  <tr>
                    <th scope="col">Bandera</th>
                    <th scope="col">País</th>
                    <th scope="col">Código</th>
                    <th scope="col">Idioma</th>
                    <th scope="col">Saludo Informal</th>
                    <th scope="col">Saludo Formal</th>
                    <th scope="col">Estado</th>
                    <th scope="col">Acciones</th>
                  </tr>
                </thead>
                <tbody>
                  {currentItems.map((greeting) => (
                    <tr key={greeting._id}>
                      <td>
                        {greeting.flagUrl ? (
                          <img
                            src={DOMPurify.sanitize(greeting.flagUrl)}
                            alt={`Bandera de ${DOMPurify.sanitize(greeting.countryName || '')}`}
                            className="flag-img"
                            width="32"
                            height="24"
                            loading="lazy"
                          />
                        ) : (
                          <span aria-label="Sin bandera">—</span>
                        )}
                      </td>
                      <td>{DOMPurify.sanitize(greeting.countryName || '')}</td>
                      <td>{DOMPurify.sanitize(greeting.countryCode || '')}</td>
                      <td>{DOMPurify.sanitize(greeting.language || '')}</td>
                      <td>{DOMPurify.sanitize(greeting.greeting || '')}</td>
                      <td>{DOMPurify.sanitize(greeting.formalGreeting || '')}</td>
                      <td>
                        <span
                          className={`status-badge ${greeting.isActive ? 'status-active' : 'status-inactive'}`}
                        >
                          {greeting.isActive ? 'Activo' : 'Inactivo'}
                        </span>
                      </td>
                      <td className="actions-cell">
                        <button
                          onClick={() => handleToggleStatus(greeting)}
                          className={`btn btn-toggle ${greeting.isActive ? 'btn-deactivate' : 'btn-activate'}`}
                          aria-label={`${greeting.isActive ? 'Desactivar' : 'Activar'} saludo de ${greeting.countryName}`}
                        >
                          {greeting.isActive ? 'Desactivar' : 'Activar'}
                        </button>
                        <button
                          onClick={() => handleDeleteClick(greeting)}
                          className="btn btn-delete"
                          aria-label={`Eliminar saludo de ${greeting.countryName}`}
                        >
                          Eliminar
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {totalPages > 1 && (
            <nav className="pagination" aria-label="Paginación de saludos">
              <button
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                aria-label="Página anterior"
                className="pagination-btn"
              >
                &laquo; Anterior
              </button>

              {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                <button
                  key={page}
                  onClick={() => handlePageChange(page)}
                  className={`pagination-btn ${currentPage === page ? 'pagination-btn-active' : ''}`}
                  aria-label={`Ir a página ${page}`}
                  aria-current={currentPage === page ? 'page' : undefined}
                >
                  {page}
                </button>
              ))}

              <button
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages}
                aria-label="Página siguiente"
                className="pagination-btn"
              >
                Siguiente &raquo;
              </button>
            </nav>
          )}
        </>
      )}

      {showConfirmModal && selectedGreeting && (
        <ConfirmModal
          message={`¿Estás seguro de que deseas eliminar el saludo de "${DOMPurify.sanitize(selectedGreeting.countryName || '')}"? Esta acción no se puede deshacer.`}
          onConfirm={handleConfirmDelete}
          onCancel={() => {
            setShowConfirmModal(false);
            setSelectedGreeting(null);
          }}
        />
      )}
    </div>
  );
};

export default GreetingTable;

import { createContext, useContext, useReducer, useCallback, useMemo } from 'react';
import DOMPurify from 'dompurify';

const GreetingContext = createContext(undefined);
const GreetingDispatchContext = createContext(undefined);

const ACTIONS = {
  SET_GREETINGS_LIST: 'SET_GREETINGS_LIST',
  SELECT_COUNTRY: 'SELECT_COUNTRY',
  SET_LOADING: 'SET_LOADING',
  SET_ERROR: 'SET_ERROR',
  TOGGLE_FORMAL_MODE: 'TOGGLE_FORMAL_MODE',
  RESET_SELECTION: 'RESET_SELECTION',
  CLEAR_ERROR: 'CLEAR_ERROR',
};

const initialState = {
  selectedCountry: null,
  greetingsList: [],
  loadingStatus: 'idle',
  errorMessage: null,
  activeLanguage: null,
  isFormalMode: false,
};

function reducer(state, action) {
  switch (action.type) {
    case ACTIONS.SET_GREETINGS_LIST:
      return {
        ...state,
        greetingsList: action.payload,
        loadingStatus: 'success',
      };
    case ACTIONS.SELECT_COUNTRY:
      return {
        ...state,
        selectedCountry: action.payload,
        activeLanguage: action.payload ? action.payload.language : null,
      };
    case ACTIONS.SET_LOADING:
      return {
        ...state,
        loadingStatus: action.payload,
      };
    case ACTIONS.SET_ERROR:
      return {
        ...state,
        loadingStatus: 'error',
        errorMessage: DOMPurify.sanitize(action.payload),
      };
    case ACTIONS.TOGGLE_FORMAL_MODE:
      return {
        ...state,
        isFormalMode: !state.isFormalMode,
      };
    case ACTIONS.RESET_SELECTION:
      return {
        ...state,
        selectedCountry: null,
        activeLanguage: null,
      };
    case ACTIONS.CLEAR_ERROR:
      return {
        ...state,
        errorMessage: null,
        loadingStatus: 'idle',
      };
    default:
      return state;
  }
}

const COUNTRY_CODE_REGEX = /^[A-Z]{2}$/;
const FLAG_URL_REGEX = /^https/;

function sanitizeCountryObject(country) {
  if (!country) return null;

  const sanitized = { ...country };

  if (sanitized.greeting !== undefined) {
    sanitized.greeting = DOMPurify.sanitize(sanitized.greeting);
  }
  if (sanitized.formalGreeting !== undefined) {
    sanitized.formalGreeting = DOMPurify.sanitize(sanitized.formalGreeting);
  }
  if (sanitized.countryName !== undefined) {
    sanitized.countryName = DOMPurify.sanitize(sanitized.countryName);
  }
  if (sanitized.language !== undefined) {
    sanitized.language = DOMPurify.sanitize(sanitized.language);
  }
  if (sanitized.countryCode !== undefined) {
    sanitized.countryCode = COUNTRY_CODE_REGEX.test(sanitized.countryCode)
      ? sanitized.countryCode
      : '';
  }
  if (sanitized.flagUrl !== undefined) {
    sanitized.flagUrl = FLAG_URL_REGEX.test(sanitized.flagUrl)
      ? sanitized.flagUrl
      : '';
  }

  return sanitized;
}

function sanitizeGreetingsList(list) {
  if (!Array.isArray(list)) return [];

  return list.map((item) => {
    const sanitized = { ...item };

    if (sanitized.greeting !== undefined) {
      sanitized.greeting = DOMPurify.sanitize(sanitized.greeting);
    }
    if (sanitized.formalGreeting !== undefined) {
      sanitized.formalGreeting = DOMPurify.sanitize(sanitized.formalGreeting);
    }
    if (sanitized.countryName !== undefined) {
      sanitized.countryName = DOMPurify.sanitize(sanitized.countryName);
    }
    if (sanitized.language !== undefined) {
      sanitized.language = DOMPurify.sanitize(sanitized.language);
    }
    if (sanitized.countryCode !== undefined) {
      sanitized.countryCode = COUNTRY_CODE_REGEX.test(sanitized.countryCode)
        ? sanitized.countryCode
        : '';
    }
    if (sanitized.flagUrl !== undefined) {
      sanitized.flagUrl = FLAG_URL_REGEX.test(sanitized.flagUrl)
        ? sanitized.flagUrl
        : '';
    }

    return sanitized;
  });
}

export function GreetingProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const loadGreetings = useCallback(
    (greetingsArray) => {
      const sanitizedList = sanitizeGreetingsList(greetingsArray);
      dispatch({ type: ACTIONS.SET_GREETINGS_LIST, payload: sanitizedList });
    },
    [dispatch]
  );

  const selectCountry = useCallback(
    (countryObject) => {
      const sanitized = sanitizeCountryObject(countryObject);
      dispatch({ type: ACTIONS.SELECT_COUNTRY, payload: sanitized });
    },
    [dispatch]
  );

  const setLoading = useCallback(
    (isLoading) => {
      dispatch({
        type: ACTIONS.SET_LOADING,
        payload: isLoading ? 'loading' : 'idle',
      });
    },
    [dispatch]
  );

  const setError = useCallback(
    (message) => {
      dispatch({ type: ACTIONS.SET_ERROR, payload: message });
    },
    [dispatch]
  );

  const toggleFormalMode = useCallback(() => {
    dispatch({ type: ACTIONS.TOGGLE_FORMAL_MODE });
  }, [dispatch]);

  const resetSelection = useCallback(() => {
    dispatch({ type: ACTIONS.RESET_SELECTION });
  }, [dispatch]);

  const clearError = useCallback(() => {
    dispatch({ type: ACTIONS.CLEAR_ERROR });
  }, [dispatch]);

  const actions = useMemo(
    () => ({
      loadGreetings,
      selectCountry,
      setLoading,
      setError,
      toggleFormalMode,
      resetSelection,
      clearError,
    }),
    [
      loadGreetings,
      selectCountry,
      setLoading,
      setError,
      toggleFormalMode,
      resetSelection,
      clearError,
    ]
  );

  const stateValue = useMemo(() => state, [state]);

  const dispatchValue = useMemo(
    () => ({ dispatch, actions }),
    [dispatch, actions]
  );

  return (
    <GreetingContext.Provider value={stateValue}>
      <GreetingDispatchContext.Provider value={dispatchValue}>
        {children}
      </GreetingDispatchContext.Provider>
    </GreetingContext.Provider>
  );
}

export function useGreetingState() {
  const context = useContext(GreetingContext);
  if (context === undefined) {
    throw new Error(
      'useGreetingState debe usarse dentro de un GreetingProvider'
    );
  }
  return context;
}

export function useGreetingActions() {
  const context = useContext(GreetingDispatchContext);
  if (context === undefined) {
    throw new Error(
      'useGreetingActions debe usarse dentro de un GreetingProvider'
    );
  }
  return context.actions;
}

export function useSelectedCountry() {
  const context = useContext(GreetingContext);
  if (context === undefined) {
    throw new Error(
      'useSelectedCountry debe usarse dentro de un GreetingProvider'
    );
  }
  return context.selectedCountry;
}

export function useGreetingsList() {
  const context = useContext(GreetingContext);
  if (context === undefined) {
    throw new Error(
      'useGreetingsList debe usarse dentro de un GreetingProvider'
    );
  }
  return context.greetingsList;
}

export function useLoadingStatus() {
  const context = useContext(GreetingContext);
  if (context === undefined) {
    throw new Error(
      'useLoadingStatus debe usarse dentro de un GreetingProvider'
    );
  }
  return {
    loadingStatus: context.loadingStatus,
    errorMessage: context.errorMessage,
  };
}

import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import DOMPurify from 'dompurify';

const useGreetings = () => {
  const [greetings, setGreetings] = useState([]);
  const [selectedGreeting, setSelectedGreeting] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  const abortControllerRef = useRef(null);

  const fetchGreetings = useCallback(async () => {
    const apiUrl = process.env.REACT_APP_API_URL;

    if (!apiUrl) {
      setError('API URL no configurada');
      return;
    }

    setLoading(true);
    setError(null);

    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const response = await fetch(`${apiUrl}/api/greetings`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP error ${response.status}`);
      }

      const data = await response.json();

      const sanitizedData = data.map((item) => ({
        ...item,
        greeting: DOMPurify.sanitize(item.greeting),
        formalGreeting: DOMPurify.sanitize(item.formalGreeting),
        countryName: DOMPurify.sanitize(item.countryName),
      }));

      setGreetings(sanitizedData);
    } catch (err) {
      if (err.name === 'AbortError') {
        return;
      }
      setError('No se pudieron cargar los saludos. Intenta de nuevo.');
    } finally {
      setLoading(false);
    }
  }, []);

  const selectGreeting = useCallback(
    (countryCode) => {
      const found = greetings.find((item) => item.countryCode === countryCode);
      if (found) {
        setSelectedGreeting(found);
      } else {
        setSelectedGreeting(null);
        console.warn(`Greeting not found for countryCode: ${countryCode}`);
      }
    },
    [greetings]
  );

  const clearSelection = () => {
    setSelectedGreeting(null);
    setSearchTerm('');
  };

  const handleSearch = useCallback((term) => {
    const sanitized = DOMPurify.sanitize(term);
    const processed = sanitized.toLowerCase().trim();
    setSearchTerm(processed);
  }, []);

  const filteredGreetings = useMemo(() => {
    if (!searchTerm) {
      return greetings;
    }
    return greetings.filter(
      (item) =>
        (item.countryName && item.countryName.toLowerCase().includes(searchTerm)) ||
        (item.language && item.language.toLowerCase().includes(searchTerm)) ||
        (item.greeting && item.greeting.toLowerCase().includes(searchTerm))
    );
  }, [greetings, searchTerm]);

  useEffect(() => {
    fetchGreetings();

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [fetchGreetings]);

  return {
    greetings: filteredGreetings,
    selectedGreeting,
    loading,
    error,
    searchTerm,
    fetchGreetings,
    selectGreeting,
    clearSelection,
    handleSearch,
  };
};

export default useGreetings;

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { authService } from '../services/authService';

const useAuth = () => {
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  const navigate = useNavigate();

  const verifyStoredToken = (token) => {
    try {
      const parts = token.split('.');
      if (parts.length !== 3) {
        throw new Error('Token malformado');
      }

      const payload = JSON.parse(atob(parts[1]));

      const currentTime = Date.now() / 1000;
      if (payload.exp && payload.exp < currentTime) {
        localStorage.removeItem('adminToken');
        localStorage.removeItem('adminRefreshToken');
        setIsAuthenticated(false);
        setUser(null);
        return;
      }

      setUser({
        username: payload.username,
        role: payload.role,
      });
      setIsAuthenticated(true);
    } catch (err) {
      localStorage.removeItem('adminToken');
      localStorage.removeItem('adminRefreshToken');
      setUser(null);
      setIsAuthenticated(false);
    }
  };

  useEffect(() => {
    const token = localStorage.getItem('adminToken');

    if (token) {
      verifyStoredToken(token);
    } else {
      setIsAuthenticated(false);
      setUser(null);
    }

    setIsLoading(false);
  }, []);

  const login = useCallback(async (username, password) => {
    if (!username || username.trim() === '') {
      setError('El nombre de usuario no puede estar vacío.');
      return;
    }

    if (!password || password.length < 8) {
      setError('La contraseña debe tener al menos 8 caracteres.');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const response = await authService.login({ username: username.trim(), password });

      const { token, refreshToken, user: userData } = response.data;

      localStorage.setItem('adminToken', token);

      if (refreshToken) {
        localStorage.setItem('adminRefreshToken', refreshToken);
      }

      setUser(userData);
      setIsAuthenticated(true);

      navigate('/admin/dashboard');
    } catch (err) {
      const serverMessage =
        err?.response?.data?.message || err?.response?.data?.error || null;

      const safeMessage =
        serverMessage && typeof serverMessage === 'string' && serverMessage.length < 200
          ? serverMessage
          : 'Credenciales inválidas. Por favor, verifica tu usuario y contraseña.';

      setError(safeMessage);
      setIsAuthenticated(false);
    } finally {
      setIsLoading(false);
    }
  }, [navigate]);

  const logout = useCallback(() => {
    localStorage.removeItem('adminToken');
    localStorage.removeItem('adminRefreshToken');

    setUser(null);
    setIsAuthenticated(false);
    setError(null);

    try {
      authService.logout().catch(() => {});
    } catch (_) {}

    navigate('/admin/login', { replace: true });
  }, [navigate]);

  const refreshAccessToken = useCallback(async () => {
    const storedRefreshToken = localStorage.getItem('adminRefreshToken');

    if (!storedRefreshToken) {
      logout();
      return null;
    }

    try {
      const response = await authService.refreshToken(storedRefreshToken);

      const { token: newToken } = response.data;

      localStorage.setItem('adminToken', newToken);

      return newToken;
    } catch (err) {
      logout();
      return null;
    }
  }, [logout]);

  const getAuthHeader = () => {
    const token = localStorage.getItem('adminToken');

    if (!token) {
      return {};
    }

    return {
      Authorization: `Bearer ${token}`,
    };
  };

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    user,
    isAuthenticated,
    isLoading,
    error,
    login,
    logout,
    refreshAccessToken,
    getAuthHeader,
    clearError,
  };
};

export default useAuth;

