import axios from 'axios';
import DOMPurify from 'dompurify';

const TOKEN_KEY = 'auth_access_token';
const REFRESH_TOKEN_KEY = 'auth_refresh_token';

const authAxios = axios.create({
  baseURL: `${process.env.REACT_APP_API_URL}/api/auth`,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

authAxios.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem(TOKEN_KEY);
    if (token) {
      config.headers['Authorization'] = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

authAxios.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    if (
      error.response &&
      error.response.status === 401 &&
      !originalRequest._retry
    ) {
      originalRequest._retry = true;
      try {
        const newAccessToken = await refreshToken();
        originalRequest.headers['Authorization'] = `Bearer ${newAccessToken}`;
        return authAxios(originalRequest);
      } catch (refreshError) {
        logout();
        return Promise.reject(new Error('Session expired. Please log in again.'));
      }
    }

    const message =
      error.response && error.response.data && error.response.data.message
        ? error.response.data.message
        : 'An unexpected error occurred. Please try again.';

    return Promise.reject(new Error(message));
  }
);

export const login = async (username, password) => {
  const sanitizedUsername = DOMPurify.sanitize(username);
  const sanitizedPassword = DOMPurify.sanitize(password);

  const response = await authAxios.post('/login', {
    username: sanitizedUsername,
    password: sanitizedPassword,
  });

  const { accessToken, refreshToken: receivedRefreshToken, user } = response.data;

  localStorage.setItem(TOKEN_KEY, accessToken);
  localStorage.setItem(REFRESH_TOKEN_KEY, receivedRefreshToken);

  return {
    username: user.username,
    role: user.role,
  };
};

export const logout = () => {
  localStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(REFRESH_TOKEN_KEY);

  (async () => {
    try {
      await authAxios.post('/logout');
    } catch (_error) {
    }
  })();
};

const refreshToken = async () => {
  const storedRefreshToken = localStorage.getItem(REFRESH_TOKEN_KEY);

  if (!storedRefreshToken) {
    return Promise.reject(new Error('No active session found.'));
  }

  const response = await authAxios.post('/refresh', {
    refreshToken: storedRefreshToken,
  });

  const { accessToken, refreshToken: rotatedRefreshToken } = response.data;

  localStorage.setItem(TOKEN_KEY, accessToken);

  if (rotatedRefreshToken) {
    localStorage.setItem(REFRESH_TOKEN_KEY, rotatedRefreshToken);
  }

  return accessToken;
};

export const getToken = () => {
  return localStorage.getItem(TOKEN_KEY) || null;
};

export const isAuthenticated = () => {
  const token = getToken();

  if (!token) {
    return false;
  }

  try {
    const parts = token.split('.');
    if (parts.length !== 3) {
      return false;
    }

    const payloadBase64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
    const payloadJson = atob(payloadBase64);
    const payload = JSON.parse(payloadJson);

    const currentTimestampInSeconds = Math.floor(Date.now() / 1000);

    if (payload.exp && payload.exp > currentTimestampInSeconds) {
      return true;
    }

    return false;
  } catch (_error) {
    return false;
  }
};

import DOMPurify from 'dompurify';

/**
 * @module sanitize
 * @description Módulo utilitario de sanitización del lado cliente.
 * Centraliza todas las funciones de limpieza y validación de datos antes de
 * renderizarlos en el DOM o enviarlos al backend.
 * Librería utilizada: DOMPurify
 *
 * ⚠️  ADVERTENCIA: Este archivo es crítico para la seguridad XSS del cliente.
 * Cualquier modificación debe ser revisada exhaustivamente antes de aplicarse.
 */

const sanitizeHTML = (input) => {
  if (typeof input !== 'string') {
    return '';
  }

  try {
    const config = {
      ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'span'],
      ALLOWED_ATTR: ['class'],
      FORBID_ATTR: ['style', 'onerror', 'onload', 'onclick', 'onmouseover'],
      ALLOW_DATA_ATTR: false,
      FORBID_CONTENTS: ['script', 'style'],
      FORCE_BODY: false,
    };

    return DOMPurify.sanitize(input, config);
  } catch {
    return '';
  }
};

const sanitizeText = (input) => {
  if (typeof input !== 'string') {
    return '';
  }

  try {
    const config = {
      ALLOWED_TAGS: [],
      ALLOWED_ATTR: [],
      KEEP_CONTENT: true,
    };

    const sanitized = DOMPurify.sanitize(input, config);
    return sanitized.trim();
  } catch {
    return '';
  }
};

const sanitizeCountryCode = (input) => {
  if (typeof input !== 'string') {
    return '';
  }

  const uppercased = input.toUpperCase();
  const trimmed = uppercased.trim();
  const pattern = /^[A-Z]{2}$/;

  if (!pattern.test(trimmed)) {
    return '';
  }

  return trimmed;
};

const sanitizeGreetingText = (input) => {
  if (typeof input !== 'string') {
    return '';
  }

  try {
    const cleaned = sanitizeText(input);
    const limited = cleaned.length > 200 ? cleaned.slice(0, 200) : cleaned;
    return limited;
  } catch {
    return '';
  }
};

const sanitizeAdminInput = (input) => {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    return {};
  }

  try {
    const sanitized = {};

    for (const key of Object.keys(input)) {
      const value = input[key];

      if (typeof value === 'string') {
        sanitized[key] = sanitizeText(value);
      } else {
        sanitized[key] = value;
      }
    }

    return sanitized;
  } catch {
    return {};
  }
};

export {
  sanitizeHTML,
  sanitizeText,
  sanitizeCountryCode,
  sanitizeGreetingText,
  sanitizeAdminInput,
};

