});

// ─── CORS ─────────────────────────────────────────────────────────────────────

const corsOptions = {
  origin: function (origin, callback) {
    if (!origin) {
      return callback(null, true);
    }

    if (!FRONTEND_URL) {
      return callback(
        new Error(
