const deepSanitizeStrings = (req, res, next) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return next();
    }

    if (process.env.NODE_ENV !== 'production') {
      console.log(`[deepSanitizeStrings] Ejecutado en ${req.method} ${req.path}`);
    }

    const sanitizeValue = (value) => {
      if (typeof value === 'string') {
        return value.trim().replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');
      }
      if (Array.isArray(value)) {
        return value.map((item) => sanitizeValue(item));
      }
      if (value !== null && typeof value === 'object') {
        const sanitized = {};
        for (const key of Object.keys(value)) {
          sanitized[key] = sanitizeValue(value[key]);
        }
        return sanitized;
      }
      return value;
    };

    req.body = sanitizeValue(req.body);
    next();
  } catch (err) {
    console.error('[deepSanitizeStrings] Error durante sanitización:', err);
    next();
  }
};

const sanitizeQueryParams = (req, res, next) => {
  for (const key of Object.keys(req.query)) {
    if (typeof req.query[key] === 'string') {
      req.query[key] = req.query[key].trim().slice(0, 200);
    } else {
      req.query[key] = undefined;
    }
  }
  next();
};

const sanitizeMiddlewares = [
  mongoSanitize({ replaceWith: '_' }),
  xssClean(),
  deepSanitizeStrings,
  sanitizeQueryParams,
];

module.exports = { sanitizeMiddlewares, deepSanitizeStrings };

const { validationResult } = require('express-validator');

const handleValidationErrors = (req, res, next) => {
  const result = validationResult(req);

  if (!result.isEmpty()) {
    const errors = result.array().map((error) => ({
      field: error.path || error.param || error.field,
      msg: error.msg,
    }));

    return res.status(422).json({
      success: false,
      message: 'Validation failed',
      errors,
    });
  }

  next();
};

const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map((validation) => validation.run(req)));

    handleValidationErrors(req, res, next);
  };
};

module.exports = {
  handleValidationErrors,
  validate,
};

const AppError = class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
};

const handleMongooseErrors = (err) => {
  if (err.name === 'CastError') {
    const message = `Valor inválido para el campo '${err.path}': ${err.value}`;
    return new AppError(message, 400);
  }

  if (err.name === 'ValidationError') {
    const messages = Object.values(err.errors).map((el) => el.message);
    const message = `Datos de entrada inválidos: ${messages.join('. ')}`;
    return new AppError(message, 400);
  }

  if (err.code === 11000) {
    const field = Object.keys(err.keyValue)[0];
    const message = `El campo '${field}' ya existe. Por favor usa un valor diferente`;
    return new AppError(message, 409);
  }

  return err;
};

const handleJWTErrors = (err) => {
  if (err.name === 'JsonWebTokenError') {
    return new AppError('Token inválido o malformado. Por favor inicia sesión nuevamente', 401);
  }

  if (err.name === 'TokenExpiredError') {
    return new AppError('Tu sesión ha expirado. Por favor inicia sesión nuevamente', 401);
  }

  return err;
};

const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    message: err.message,
    stack: err.stack,
    error: err,
  });
};

const sendErrorProd = (err, res) => {
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
    });
  } else {
    console.error('ERROR INESPERADO:', {
      timestamp: new Date().toISOString(),
      message: err.message,
      stack: err.stack,
      error: err,
    });

    res.status(500).json({
      status: 'error',
      message: 'Algo salió mal, intenta de nuevo más tarde',
    });
  }
};

const errorMiddleware = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  let error = Object.assign(Object.create(Object.getPrototypeOf(err)), err);
  error.message = err.message;

  error = handleMongooseErrors(error);
  error = handleJWTErrors(error);

  console.error(
    `[${new Date().toISOString()}] ${req.method} ${req.originalUrl} - ${error.message}`
  );

  const env = process.env.NODE_ENV;

  if (env === 'development') {
    sendErrorDev(error, res);
  } else {
    sendErrorProd(error, res);
  }
};

module.exports = errorMiddleware;
module.exports.AppError = AppError;

const mongoose = require('mongoose');

const greetingSchema = new mongoose.Schema(
