const { validationResult } = require('express-validator');
const greetingService = require('../services/greeting.service');

const getAllGreetings = async (req, res, next) => {
  try {
    const page = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 20));
    const isActive = req.query.isActive !== undefined
      ? req.query.isActive === 'true'
      : undefined;

    const result = await greetingService.getAllGreetings({ page, limit, isActive });

    return res.status(200).json({
      success: true,
      data: result.data,
      metadata: {
        totalCount: result.totalCount,
        currentPage: page,
        totalPages: result.totalPages,
      },
    });
  } catch (error) {
    return next(error);
  }
};

const getGreetingByCountryCode = async (req, res, next) => {
  try {
    const countryCode = req.params.countryCode.toUpperCase();

    const greeting = await greetingService.getGreetingByCountryCode(countryCode);

    if (!greeting) {
      return res.status(404).json({
        success: false,
        message: 'Greeting not found for the specified country code.',
      });
    }

    return res.status(200).json({
      success: true,
      data: greeting,
    });
  } catch (error) {
    return next(error);
  }
};

const createGreeting = async (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(422).json({
        success: false,
        errors: errors.array(),
      });
    }

    const {
      countryCode,
      countryName,
      language,
      greeting,
      formalGreeting,
      flagUrl,
      isActive,
    } = req.body;

    const greetingData = {
      countryCode,
      countryName,
      language,
      greeting,
      formalGreeting,
      flagUrl,
      isActive,
    };

    const created = await greetingService.createGreeting(greetingData);

    return res.status(201).json({
      success: true,
      data: created,
    });
  } catch (error) {
    if (error.code === 11000) {
      return res.status(409).json({
        success: false,
        message: 'A greeting for this country code already exists.',
      });
    }
    return next(error);
  }
};

const updateGreeting = async (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(422).json({
        success: false,
        errors: errors.array(),
      });
    }

    const countryCode = req.params.countryCode.toUpperCase();

    const {
      countryName,
      language,
      greeting,
      formalGreeting,
      flagUrl,
      isActive,
    } = req.body;

    const updateData = {
      countryName,
      language,
      greeting,
      formalGreeting,
      flagUrl,
      isActive,
    };

    Object.keys(updateData).forEach(
      (key) => updateData[key] === undefined && delete updateData[key]
    );

    const updated = await greetingService.updateGreeting(countryCode, updateData);

    if (!updated) {
      return res.status(404).json({
        success: false,
        message: 'Greeting not found for the specified country code.',
      });
    }

    return res.status(200).json({
      success: true,
      data: updated,
    });
  } catch (error) {
    return next(error);
  }
};

const deleteGreeting = async (req, res, next) => {
  try {
    const countryCode = req.params.countryCode.toUpperCase();

    const deleted = await greetingService.deleteGreeting(countryCode);

    if (!deleted) {
      return res.status(404).json({
        success: false,
        message: 'Greeting not found for the specified country code.',
      });
    }

    return res.status(200).json({
      success: true,
      message: 'Greeting deleted successfully.',
    });
  } catch (error) {
    return next(error);
  }
};

const searchGreetings = async (req, res, next) => {
  try {
    const { q } = req.query;

    if (!q || q.trim() === '') {
      return res.status(400).json({
        success: false,
        message: 'Search parameter q is required.',
      });
    }

    if (q.length > 100) {
      return res.status(400).json({
        success: false,
        message: 'Search term must not exceed 100 characters.',
      });
    }

    const results = await greetingService.searchGreetings(q.trim());

    return res.status(200).json({
      success: true,
      data: results,
    });
  } catch (error) {
    return next(error);
  }
};

module.exports = {
  getAllGreetings,
  getGreetingByCountryCode,
  createGreeting,
  updateGreeting,
  deleteGreeting,
  searchGreetings,
};

const authService = require('../services/auth.service');

const COOKIE_NAME = 'refreshToken';
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

const getCookieOptions = () => ({
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production',
  sameSite: 'Strict',
  maxAge: SEVEN_DAYS_MS,
});

const login = async (req, res, next) => {
  try {
    const { username, password } = req.body;

    const { accessToken, refreshToken, user } = await authService.login(username, password);

    res.cookie(COOKIE_NAME, refreshToken, getCookieOptions());

    return res.status(200).json({
      success: true,
      data: {
        accessToken,
        user,
      },
      message: 'Sesión iniciada exitosamente',
    });
  } catch (error) {
    return next(error);
  }
};

const logout = async (req, res, next) => {
  try {
    const existingToken = req.cookies[COOKIE_NAME];

    if (existingToken) {
      if (typeof authService.invalidateRefreshToken === 'function') {
        await authService.invalidateRefreshToken(existingToken);
      }
    }

    res.cookie(COOKIE_NAME, '', {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'Strict',
      maxAge: 0,
    });

    return res.status(200).json({
      success: true,
      data: null,
      message: 'Sesión cerrada exitosamente',
    });
  } catch (error) {
    return next(error);
  }
};

const refreshToken = async (req, res, next) => {
  const token = req.cookies[COOKIE_NAME];

  if (!token) {
    return res.status(401).json({
      success: false,
      data: null,
      message: 'No autorizado',
    });
  }

  try {
    const result = await authService.refreshToken(token);

    if (result.refreshToken) {
      res.cookie(COOKIE_NAME, result.refreshToken, getCookieOptions());
    }

    return res.status(200).json({
      success: true,
      data: {
        accessToken: result.accessToken,
      },
      message: 'Token renovado exitosamente',
    });
  } catch (error) {
    return next(error);
  }
};

exports.login = login;
exports.logout = logout;
exports.refreshToken = refreshToken;

